function renderAgents() { const s = store.get(); const selected = agents.find(a => a.id === s.selectedAgent && a.session === s.session); if (selected) {
    renderAgentDetail(selected);
    return;
} const list = sessionAgents().filter(a => (s.agentFilter === 'all' || a.status === s.agentFilter) && (a.name + ' ' + a.task).toLowerCase().includes(s.agentQuery.toLowerCase())); $('#railContent').innerHTML = `<div class="rail-top"><div class="row"><h3 class="grow">Agenti della sessione</h3>${badge(sessionAgents().length + ' demo')}</div><button class="btn" data-action="open-graph">${icon('branch')}Apri visuale diagramma</button><div class="searchbox">${icon('search')}<input id="agentSearch" value="${esc(s.agentQuery)}" placeholder="Cerca nome, ruolo o task…" aria-label="Cerca agenti"></div><div class="filters">${[['all', 'Tutti'], ['active', 'Attivi'], ['waiting', 'In attesa'], ['error', 'Errori'], ['done', 'Terminati']].map(([v, t]) => `<button data-action="agent-filter" data-value="${v}" aria-pressed="${s.agentFilter === v}">${t}</button>`).join('')}</div></div><div class="scroll">${list.map(a => `<div class="agent-row" role="button" tabindex="0" data-agent="${a.id}" aria-label="Dettaglio ${a.name}"><div class="agent-icon">${icon(a.id === 'lead' ? 'branch' : 'robot')}</div><div class="grow"><div class="row"><h3 class="grow">${esc(a.name)}</h3>${stateBadge(a)}</div><p>${esc(a.task)}</p><div class="row small muted"><span>${esc(a.tool)}</span><span>·</span><span>${a.duration}</span><span class="grow"></span><span>${agents.filter(x => x.parent === a.id).length} figli</span></div></div></div>`).join('') || '<div class="empty"><h3>Nessun agente in questa vista</h3><p>Cambia filtro o sessione.</p></div>'}</div><div class="rail-foot"><p class="small muted">La selezione resta nella sessione. Le altre tab rimangono sempre accessibili.</p></div>`; }
function renderAgentDetail(a) { const s = store.get(); $('#railContent').innerHTML = `<div class="rail-top"><div class="row"><button data-action="agent-list">${icon('left')}Tutti gli agenti</button><span class="grow"></span><button data-action="open-graph" aria-label="Apri questo agente nel diagramma" title="Apri nel diagramma">${icon('branch')}</button></div><div class="row"><div class="agent-icon">${icon('robot')}</div><div class="grow"><h3>${esc(a.name)}</h3><p class="small muted">${esc(a.role)}</p></div>${stateBadge(a)}</div><div class="filters">${[['overview', 'Panoramica'], ['files', 'File'], ['events', 'Eventi']].map(([v, t]) => `<button data-action="detail-section" data-value="${v}" aria-pressed="${s.detailSection === v}">${t}</button>`).join('')}</div></div><div class="scroll"><div class="detail" id="agentDetail" data-agent-id="${a.id}">${s.detailSection === 'overview' ? `<div><div class="eyebrow" style="margin-bottom:8px">Task corrente</div><div class="task">${esc(a.task)}</div></div><dl class="kv"><dt>Modello</dt><dd>${esc(a.model)}</dd><dt>Durata</dt><dd>${scenario === 'partial' ? '—' : a.duration}</dd><dt>Attrezzo</dt><dd>${esc(a.tool)}</dd><dt>Parent</dt><dd>${esc(agents.find(x => x.id === a.parent)?.name || 'Sessione principale')}</dd><dt>Esecuzione</dt><dd class="mono">${a.run} · fixture</dd><dt>Permessi</dt><dd>${a.id === 'audit' ? 'Sola lettura' : 'Area isolata demo'}</dd><dt>Token / costo</dt><dd>— / —</dd></dl><div class="notice">${a.status === 'error' ? 'Errore demo: la finestra di test non era disponibile. Nessun processo reale è in errore.' : 'Stato dimostrativo. Nessuna esecuzione reale collegata.'}</div>${a.status === 'error' ? '<button class="btn" data-action="retry-agent" data-id="' + a.id + '">Simula retry</button>' : ''}<div class="row"><button class="btn" data-action="isolate" data-id="${a.id}">Isola nel diagramma</button><button data-action="follow" data-id="${a.id}" aria-pressed="${graph.follow}">Segui</button></div><div><h3 style="margin-bottom:8px">File coinvolti</h3>${a.files.map(id => fileLink(id)).join('')}</div><div class="task"><b>Sintesi disponibile</b><p>Il task riguarda ${esc(a.files.join(', '))}. Il laboratorio mostra una sintesi del lavoro, non pensieri interni del modello.</p></div>` : s.detailSection === 'files' ? `<h3>File letti / modificati</h3>${a.files.map(id => fileLink(id)).join('')}<button class="btn" data-action="view" data-value="review">Apri differenze demo</button><p class="small muted">La provenienza distingue le letture dalle scritture dell’agente. I collegamenti puntano alle fixture.</p>` : `<h3>Eventi della fixture</h3>${eventRows(a)}<p class="small muted">Eventi riproducibili dal cursore del diagramma; nessun WebSocket collegato.</p>`}</div></div>`; }
function fileLink(id) { return `<button class="filelink" data-action="reveal-file" data-id="${esc(id)}">${icon('file')}<span class="truncate">${esc(id)}</span><span class="grow"></span><span class="muted">↗</span></button>`; }
function eventRows(a) { return [['00:00', 'Task assegnato'], ['00:08', 'Lettura di ' + (a.files[0] || '(file non disponibile)')], ['00:22', a.tool + ' · ' + a.task], ['00:35', a.status === 'error' ? 'Errore simulato, disponibile il retry' : 'Checkpoint della fixture']].map(([t, d]) => `<div class="event"><time>${t}</time><span>${esc(d)}</span></div>`).join(''); }
function renderContext() { const list = contextFiles.map(fileBy).filter(Boolean); $('#railContent').innerHTML = `<div class="rail-top"><h3>Context della sessione</h3><p class="small muted">File aggiunti in questa prova. Nessun invio a un modello.</p></div><div class="scroll"><div class="detail">${list.length ? list.map(f => `<div class="row grow">${fileLink(f.id)}<button class="danger" data-action="remove-context" data-id="${esc(f.id)}" aria-label="Rimuovi ${esc(f.id)} dal Context">${icon('x')}</button></div>`).join('') : '<div class="empty"><h3>Nessun file aggiunto</h3><p>In File seleziona uno o più elementi, poi premi Al Context.</p></div>'}<div class="notice">Sola lettura per le analisi. Scrittura, comandi e azioni esterne restano autorizzazioni separate nel flusso proposto.</div></div></div>`; }
function renderProcesses() { $('#railContent').innerHTML = `<div class="rail-top"><h3>Processi</h3><p class="small muted">Vista di controllo per verificare che il dettaglio Agenti non la blocchi.</p></div><div class="detail"><div class="row">${icon('terminal')}<b class="grow small">Test della fixture</b>${badge('Terminato', 'good')}</div><p class="small muted">Nessun comando eseguito da questa pagina. La gestione reale dei processi non è modificata dal laboratorio.</p><pre class="task mono">node --test …\n[output dimostrativo]</pre></div>`; }
